        require(msg.sender != other);
        require(address(this).balance >= amount);

        (uint otherBalBefore, ) = c.Acc(other);
        (uint senderBalBefore, ) = c.Acc(address(this));

        c.Put{value: amount}(unlockTime);

        ( , uint senderBalAfter) = c.Acc(address(this));
        ( , uint senderUnlockAfter) = c.Acc(address(this));
