contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint depositAmount, uint unlockTime, uint collectAmount) public payable {
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        // Initial recorded balance for user should be zero in a fresh deployment.
        (uint initUnlock, uint initBalance) = c.Acc(user);
        assert(initBalance == 0);

        uint beforeContractBalance = address(c).balance;
        uint beforeTestBalance = address(this).balance;

        // Deposit.
        c.Put{value: depositAmount}(unlockTime);

        (uint postPutUnlock, uint postPutBalance) = c.Acc(user);
        uint afterPutContractBalance = address(c).balance;
        uint afterPutTestBalance = address(this).balance;

        // General rule: recorded balance increases by exactly the Ether sent, and
        // the contract's balance increases by the same amount (no fee/mint).
        assert(postPutBalance == depositAmount);
        assert(afterPutContractBalance == beforeContractBalance + depositAmount);
        assert(afterPutTestBalance + depositAmount == beforeTestBalance);

        // Attempt a withdrawal; only a successful Collect may reduce the recorded balance.
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        (uint postCollectUnlock, uint postCollectBalance) = c.Acc(user);
        uint afterCollectContractBalance = address(c).balance;
        uint afterCollectTestBalance = address(this).balance;

        if (collectReverted) {
            // On revert, neither the recorded balance nor the contract balance changes.
            assert(postCollectBalance == postPutBalance);
            assert(afterCollectContractBalance == afterPutContractBalance);
            assert(afterCollectTestBalance == afterPutTestBalance);
        } else {
            // On success, the recorded balance decreases by exactly collectAmount, the
            // contract's Ether decreases by exactly collectAmount, and the test
            // receives exactly collectAmount.
            assert(postCollectBalance + collectAmount == postPutBalance);
            assert(afterCollectContractBalance + collectAmount == afterPutContractBalance);
            assert(afterCollectTestBalance == afterPutTestBalance + collectAmount);
        }

        // The final recorded balance equals total deposits minus successful withdrawals.
        uint expectedBalance = collectReverted ? postPutBalance : postPutBalance - collectAmount;
        assert(postCollectBalance == expectedBalance);
    }

    receive() external payable {}
}

